import{A as e,E as t,c as n,d as r,h as i,p as a,t as o}from"./_plugin-vue_export-helper-mTPtt9wH.js";import{n as s}from"./navigate-y_9R8FD2.js";import{t as c}from"./CodeBlock-CsUHGuwr.js";import{t as l}from"./CTopbar-Ct1O06G3.js";var u=`# Build stage
FROM eclipse-temurin:21-jdk AS build
WORKDIR /workspace
COPY .mvn/ .mvn/
COPY mvnw pom.xml ./
RUN ./mvnw -B dependency:go-offline
COPY src ./src
RUN ./mvnw -B clean package -DskipTests

# Runtime stage
FROM eclipse-temurin:21-jre
WORKDIR /app
RUN useradd --system --uid 10001 appuser
COPY --from=build /workspace/target/*.jar app.jar
USER 10001
EXPOSE 8080
ENTRYPOINT ["java", "-XX:MaxRAMPercentage=75.0", "-jar", "/app/app.jar"]`,d=`# Pipeline concept — same immutable image digest promoted by environment
image: 123456789012.dkr.ecr.ap-southeast-1.amazonaws.com/orders@sha256:abc...

dev:
  cluster: orders-dev
  desiredCount: 1
  config: dev parameter/secret namespace
  approval: automatic after checks

stg:
  cluster: orders-stg
  desiredCount: 2
  config: stg parameter/secret namespace
  approval: integration tests pass

prod:
  cluster: orders-prod
  desiredCount: 3
  config: prod parameter/secret namespace
  approval: protected manual approval
  deployment: rolling or blue/green with alarms

# IAM: CI role may push to ECR and update the intended ECS service only.
# ECS task role: app permissions (for example read one secret, publish one queue).
# ECS execution role: pull image and write logs.`,f={name:`CloudBackendDeployPage`,components:{CTopbar:l,CodeBlock:c},data(){return{dockerCode:u,ecsDeployCode:d}},methods:{goCloud(){s(`/cloud`)}}},p={class:`deploy-page`},m={class:`deploy-wrap`},h={class:`lesson`},g={class:`lesson`};function _(o,s,c,l,u,d){let f=e(`CTopbar`),_=e(`CodeBlock`);return t(),r(`main`,p,[n(`div`,m,[i(f,{title:`☁️ Deploy Backend lên AWS`,"back-label":`AWS Cloud`,onGoHome:d.goCloud},null,8,[`onGoHome`]),s[3]||=a(`<header class="hero" data-v-cfcff595><p class="eyebrow" data-v-cfcff595>SPRING BOOT · DOCKER · AWS ECS FARGATE</p><h1 data-v-cfcff595>Đưa một backend từ dev lên production</h1><p data-v-cfcff595>Ví dụ kiến trúc cho Spring Boot API: build một image bất biến, đẩy lên ECR, chạy ECS Fargate sau ALB, kết nối RDS trong private subnet, rồi promote cùng artifact qua dev → stg → prod.</p></header><section class="lesson" data-v-cfcff595><h2 data-v-cfcff595>1. Kiến trúc chạy thực tế</h2><div class="architecture" data-v-cfcff595><div class="flow" data-v-cfcff595><span data-v-cfcff595>Client</span><b data-v-cfcff595>→</b><span data-v-cfcff595>Route 53 / TLS</span><b data-v-cfcff595>→</b><span data-v-cfcff595>ALB · public subnets</span><b data-v-cfcff595>→</b><span data-v-cfcff595>ECS Fargate · private subnets</span></div><div class="connectors" data-v-cfcff595>↓ private security-group rule · port 5432 ↓ \xA0\xA0\xA0\xA0 task role → AWS APIs</div><div class="flow secondary" data-v-cfcff595><span data-v-cfcff595>RDS Multi-AZ · private DB subnets</span><span data-v-cfcff595>Secrets Manager</span><span data-v-cfcff595>CloudWatch Logs / Metrics / Alarms</span></div><p class="diagram-note" data-v-cfcff595>Ingress chỉ tới ALB. ECS chỉ nhận traffic từ ALB security group. Database không có public address. Task nhận quyền AWS qua IAM task role, không dùng access key hardcode.</p></div><div class="env-grid" data-v-cfcff595><article data-v-cfcff595><strong data-v-cfcff595>DEV</strong><p data-v-cfcff595>Deploy tự động sau merge vào develop; dữ liệu test; ít replica; smoke test nhanh.</p></article><article data-v-cfcff595><strong data-v-cfcff595>STG</strong><p data-v-cfcff595>Promote đúng image digest đã chạy ở dev; config/service dependency gần prod; chạy integration và acceptance tests.</p></article><article data-v-cfcff595><strong data-v-cfcff595>PROD</strong><p data-v-cfcff595>Promote cùng digest sau approval; nhiều AZ; alarm, rollback plan, backup và migration tương thích ngược.</p></article></div></section><section class="lesson" data-v-cfcff595><h2 data-v-cfcff595>2. Pipeline: build một lần, promote nhiều môi trường</h2><ol class="pipeline" data-v-cfcff595><li data-v-cfcff595><strong data-v-cfcff595>Validate:</strong> compile, unit/integration tests, dependency và image scan.</li><li data-v-cfcff595><strong data-v-cfcff595>Build:</strong> tạo container image gắn commit SHA; không dùng tag <code data-v-cfcff595>latest</code> làm định danh deploy.</li><li data-v-cfcff595><strong data-v-cfcff595>Publish:</strong> push ECR image; lưu digest và metadata của build.</li><li data-v-cfcff595><strong data-v-cfcff595>Deploy DEV:</strong> cập nhật ECS task definition sang digest đó; đợi service ổn định và chạy smoke test.</li><li data-v-cfcff595><strong data-v-cfcff595>Promote STG:</strong> dùng đúng digest, đổi config/secret theo môi trường; kiểm tra API, DB migration, alarm.</li><li data-v-cfcff595><strong data-v-cfcff595>Approve PROD:</strong> cùng digest, deployment circuit breaker/health check; theo dõi error rate và latency.</li><li data-v-cfcff595><strong data-v-cfcff595>Rollback:</strong> quay task definition về revision/digest trước; migration DB phải tương thích để app cũ tiếp tục chạy.</li></ol><div class="callout" data-v-cfcff595><strong data-v-cfcff595>Không build lại cho từng môi trường.</strong> Nếu staging và production build từ source riêng, bạn không còn chắc artifact đã test chính là artifact đang phục vụ người dùng.</div></section>`,3),n(`section`,h,[s[0]||=n(`h2`,null,`3. Docker image mẫu cho Spring Boot`,-1),s[1]||=n(`p`,null,`Multi-stage build giúp image runtime chỉ chứa JRE và file ứng dụng. Chạy non-root, expose health endpoint có kiểm soát, và pin base image theo quy tắc cập nhật bảo mật của team.`,-1),i(_,{code:u.dockerCode,language:`dockerfile`},null,8,[`code`])]),n(`section`,g,[s[2]||=a(`<h2 data-v-cfcff595>4. Mỗi environment khác nhau ở đâu?</h2><div class="env-details" data-v-cfcff595><div data-v-cfcff595><h3 data-v-cfcff595>Giữ giống nhau</h3><ul data-v-cfcff595><li data-v-cfcff595>Cùng container image digest.</li><li data-v-cfcff595>Cùng kiểu task definition và health checks.</li><li data-v-cfcff595>Cùng pipeline kiểm tra, quyền triển khai có audit.</li><li data-v-cfcff595>Infrastructure định nghĩa bằng Terraform/CloudFormation, review qua version control.</li></ul></div><div data-v-cfcff595><h3 data-v-cfcff595>Thay theo môi trường</h3><ul data-v-cfcff595><li data-v-cfcff595>Database endpoint và credentials lấy từ secret store.</li><li data-v-cfcff595>CPU/memory/desired task count theo tải và chi phí.</li><li data-v-cfcff595>Domain, callback URL, feature flag và external provider settings.</li><li data-v-cfcff595>Approval gates, data classification và retention policy.</li></ul></div></div>`,2),i(_,{code:u.ecsDeployCode,language:`yaml`},null,8,[`code`])]),s[4]||=a(`<section class="lesson" data-v-cfcff595><h2 data-v-cfcff595>5. Database migration không làm deploy hỏng</h2><p data-v-cfcff595>Dùng expand-and-contract: release đầu thêm schema mới nhưng giữ schema cũ; deploy app đọc/ghi tương thích; backfill dữ liệu theo batch; chuyển app sang field mới; release sau mới xóa schema cũ. Tránh deploy migration phá vỡ trong lúc task cũ vẫn đang chạy.</p><div class="migration-flow" data-v-cfcff595><span data-v-cfcff595>Expand schema</span><b data-v-cfcff595>→</b><span data-v-cfcff595>Deploy compatible app</span><b data-v-cfcff595>→</b><span data-v-cfcff595>Backfill + verify</span><b data-v-cfcff595>→</b><span data-v-cfcff595>Contract later</span></div></section><section class="lesson" data-v-cfcff595><h2 data-v-cfcff595>6. Checklist trước và sau production deploy</h2><div class="check-grid" data-v-cfcff595><div data-v-cfcff595><h3 data-v-cfcff595>Trước deploy</h3><ul data-v-cfcff595><li data-v-cfcff595>Image digest khớp artifact đã test.</li><li data-v-cfcff595>Secrets không nằm trong image, repo hoặc log.</li><li data-v-cfcff595>DB migration tương thích task đang chạy.</li><li data-v-cfcff595>ALB health check và ECS deployment alarms có cấu hình.</li><li data-v-cfcff595>Biết ai phê duyệt và cách rollback.</li></ul></div><div data-v-cfcff595><h3 data-v-cfcff595>Sau deploy</h3><ul data-v-cfcff595><li data-v-cfcff595>ECS service ổn định, desired = running tasks.</li><li data-v-cfcff595>Health check pass ở ALB và app.</li><li data-v-cfcff595>Kiểm tra error rate, p95 latency, CPU/memory, DB connections.</li><li data-v-cfcff595>Smoke test critical endpoint, auth và luồng tạo dữ liệu.</li><li data-v-cfcff595>Ghi release/version vào dashboard và thông báo team.</li></ul></div></div><p class="interview-answer" data-v-cfcff595><strong data-v-cfcff595>Cách kể trong phỏng vấn:</strong> “We build the container once, tag it with the commit SHA, and promote the same image digest from dev to staging and production. Each environment injects its own configuration and secrets. Before production, we verify health checks and backward-compatible database migrations. If alarms fire, we roll the ECS service back to the previous task definition.”</p></section>`,2)])])}var v=o(f,[[`render`,_],[`__scopeId`,`data-v-cfcff595`]]);export{v as default};